"""Investigation result node generated by aotn_node_helper."""

from typing import Any, ClassVar, Dict, List, Optional

from ...node_base import Node, NodeContext
from ...node_category import NodeCategory


class HermesInvestigationResultNode(Node):
    """Read a finding, or check whether it is ready."""

    node_type: ClassVar[str] = 'hermes_investigation_result_node'
    display_name: ClassVar[str] = 'Investigation result'
    default_alias: ClassVar[str] = 'Investigation result'
    description: ClassVar[str] = 'Read a finding, or check whether it is ready'
    category: ClassVar[str] = NodeCategory.IO
    primary_family: ClassVar[str] = 'Inputs'
    tags: ClassVar[List[str]] = ['Hermes', 'investigation', 'incident']
    icon_name: ClassVar[str] = 'search'
    color_hint: ClassVar[str] = 'green'
    group: ClassVar[Optional[str]] = 'Hermes'
    selector_section: ClassVar[Optional[str]] = 'Text & Data'
    input_ports: ClassVar[List[str]] = ['input']
    output_ports: ClassVar[List[str]] = ['default', 'state']
    input_port_metadata: ClassVar[Dict[str, Dict[str, Any]]] = {'input': {'name': 'Request id', 'description': '', 'data_type': 'string', 'required': True, 'sources': ['upstream', 'vault', 'configured']}}
    output_port_metadata: ClassVar[Dict[str, Dict[str, Any]]] = {'default': {'name': 'Finding', 'description': 'The finding, or not ready yet / failed', 'data_type': 'string', 'required': True, 'to': ['downstream', 'vault'], 'pass_through': True}, 'state': {'name': 'State', 'description': 'ready / not ready yet / failed; for a Conditional', 'data_type': 'string', 'required': False, 'to': ['vault']}}
    default_config: ClassVar[Dict[str, Any]] = {'input_source': 'Configured', 'input_vault_key': '', 'input': '', 'transient_output': True, 'dead_drop_passthrough': False, 'transient_outputs': [], 'vault_write': False, 'vault_write_key': '', 'vault_write_description': '', 'state_vault_write': False, 'state_vault_key': '', 'state_vault_description': ''}
    config_schema: ClassVar[Dict[str, Dict[str, Any]]] = {'input_source': {'type': 'select', 'label': 'Input source', 'options': ['Upstream payload', 'Vault', 'Configured'], 'tab': 'Source', 'section': 'Required Inputs'}, 'input_vault_key': {'type': 'string', 'label': 'Input Vault key', 'required': False, 'tab': 'Source', 'section': 'Required Inputs', 'vault_type': 'string', 'visible_when': {'input_source': 'Vault'}}, 'input': {'type': 'string', 'label': 'Request id', 'description': 'Checks once. Does not wait or start Hermes.', 'tab': 'Parameters', 'visible_when': {'input_source': 'Configured'}}}
    ui_hints: ClassVar[Dict[str, Any]] = {}
    error_definitions: ClassVar[List[Dict[str, Any]]] = [{'code': 'invalid_request_id', 'description': 'Enter a valid investigation request id.', 'retryable': False}, {'code': 'request_not_found', 'description': 'This investigation request was not found.', 'retryable': False}, {'code': 'record_invalid', 'description': 'The investigation record needs checking.', 'retryable': False}, {'code': 'inbox_busy', 'description': 'The investigation inbox is busy. Try later.', 'retryable': False}, {'code': 'inbox_unreadable', 'description': 'The investigation inbox could not be read.', 'retryable': False}]

    async def execute(self, context: NodeContext) -> None:
        from ... import hermes_investigations as inbox, hermes_folder
        from ...node_errors import NodeError
        try:
            inbox.validate_outputs(self.config, state=True)
            finding, state = inbox.result(inbox.source(self.config, context, 'input'))
            if self.config.get('state_vault_write'):
                context.memory_bank.store_persistent(self.config['state_vault_key'].strip(), state, type_tag='string')
            hermes_folder.finish(self, context, finding, 'string')
        except NodeError as exc:
            context.signal_error(exc)
